"""Import the exact approved crossed-arms Feedback reference. Run from repo root."""
import base64
import hashlib
from pathlib import Path
DATA = ''
EXPECTED = '87ad79e132713f77c2cd5d4cc2a3371302c8edfa3f10661e837a5929432e1ef8'
def main():
    data = base64.b64decode(DATA, validate=True)
    if hashlib.sha256(data).hexdigest() != EXPECTED:
        raise SystemExit("Checksum mismatch; nothing written")
    target = Path("artifacts/sound-clash/art-source/feedback/feedback-crossed-arms-approved.jpeg")
    if target.exists() and target.read_bytes() != data:
        raise SystemExit("Different file already exists; preserve it and choose a new path")
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(data)
    print("Verified exact approved reference:", target)
    print("SHA256:", EXPECTED)
if __name__ == "__main__":
    main()
